), up as (
  insert into rx_hospitals (code, name)
  select code, name from src
  on conflict (code) do update set name = excluded.name, updated_at = now()
    where rx_hospitals.name is distinct from excluded.name
  returning (xmax = 0) as inserted
)
select count(*) filter (where inserted) as 新增筆數, count(*) filter (where not inserted) as 名稱更新筆數 from up;
